#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, x, y;
    cin >> n >> x >> y;
    vector<int> a(n);
    for (auto &v : a) cin >> v;
    sort(a.begin(), a.end());
    // bit s: the chosen cars can put total time s on line 1 (s <= x)
    bitset<512> bits, mask;
    bits[0] = 1;
    for (int s = 0; s <= x; s++) mask[s] = 1;
    int total = 0, answer = 0;
    for (int i = 0; i < n; i++) {
        total += a[i];
        if (total > x + y) break;
        bits = (bits | (bits << a[i])) & mask;
        // feasible when some line-1 load s has total - s <= y
        if ((bits >> max(0, total - y)).any()) answer = i + 1;
        else break;
    }
    cout << answer << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), x = nextInt(), y = nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = nextInt();
        Arrays.sort(a);
        // bit s: the chosen cars can put total time s on line 1 (s <= x)
        java.math.BigInteger bits = java.math.BigInteger.ONE;
        java.math.BigInteger mask = java.math.BigInteger.ONE.shiftLeft(x + 1).subtract(java.math.BigInteger.ONE);
        int total = 0, answer = 0;
        for (int i = 0; i < n; i++) {
            total += a[i];
            if (total > x + y) break;
            bits = bits.or(bits.shiftLeft(a[i])).and(mask);
            // feasible when some line-1 load s has total - s <= y
            if (bits.shiftRight(Math.max(0, total - y)).signum() != 0) answer = i + 1;
            else break;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"math/big"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, x, y := next(), next(), next()
	a := make([]int, n)
	for i := range a {
		a[i] = next()
	}
	sort.Ints(a)
	// bit s: the chosen cars can put total time s on line 1 (s <= x)
	bits := big.NewInt(1)
	mask := new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), uint(x+1)), big.NewInt(1))
	shifted := new(big.Int)
	total, answer := 0, 0
	for i, v := range a {
		total += v
		if total > x+y {
			break
		}
		bits.Or(bits, shifted.Lsh(bits, uint(v)))
		bits.And(bits, mask)
		// feasible when some line-1 load s has total - s <= y
		if shifted.Rsh(bits, uint(max(0, total-y))).Sign() != 0 {
			answer = i + 1
		} else {
			break
		}
	}
	fmt.Println(answer)
}
